const fs = require('fs');

function divide(dividend, divisor) {
    if (dividend === -2147483648 && divisor === -1) return 2147483647;
    let a = Math.abs(dividend);
    let b = Math.abs(divisor);
    let res = 0;
    for (let i = 31; i >= 0; i--) {
        // JavaScript bitwise operators work on 32-bit signed ints, but we use Math.pow for precision
        let bShift = b * Math.pow(2, i);
        if (a >= bShift) {
            res += Math.pow(2, i);
            a -= bShift;
        }
    }
    return (dividend > 0) === (divisor > 0) ? res : -res;
}

