int divideInts(int dividend, int divisor) {
    if (dividend == INT_MIN && divisor == -1) return INT_MAX;
    long long a = llabs((long long)dividend);
    long long b = llabs((long long)divisor);
    long long res = 0;
    for (int i = 31; i >= 0; i--) {
        if ((a >> i) >= b) {
            res += (1LL << i);
            a -= (b << i);
        }
    }
    return (dividend > 0) == (divisor > 0) ? (int)res : (int)-res;
}

int main() {
    long long d1, d2;
    if (scanf("%lld %lld", &d1, &d2) == 2) {
        printf("%d\n", divideInts((int)d1, (int)d2));
    }
